<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue'
import { listarErrores } from '../services/erroresSistema'
import type { ArchivoLog, ErrorFilters, ErrorSistema, NivelLog } from '../interfaces/erroresSistema.interface'

const rows=ref<ErrorSistema[]>([]),files=ref<ArchivoLog[]>([]),summary=ref<Partial<Record<NivelLog,number>>>({}),total=ref(0),last=ref(1),loading=ref(false),error=ref(''),selected=ref<ErrorSistema|null>(null)
const filters=reactive<ErrorFilters>({archivo:'',nivel:'',criterio:'',desde:'',hasta:'',page:1})
const criticalCount=computed(()=>Number(summary.value.emergency||0)+Number(summary.value.alert||0)+Number(summary.value.critical||0)+Number(summary.value.error||0))
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const result=await listarErrores(filters);rows.value=result.data;files.value=result.archivos;summary.value=result.resumen;total.value=result.total;last.value=result.last_page}catch(e){error.value=e instanceof Error?e.message:'No se pudo leer el historial de errores.'}finally{loading.value=false}}
function clear(){Object.assign(filters,{archivo:'',nivel:'',criterio:'',desde:'',hasta:'',page:1});load()}
function levelName(level:NivelLog){return({emergency:'Emergencia',alert:'Alerta',critical:'Crítico',error:'Error',warning:'Advertencia',notice:'Aviso',info:'Información',debug:'Depuración'} as Record<NivelLog,string>)[level]}
onMounted(()=>load())
</script>

<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Sistema / Administrador / Errores del sistema</nav><header class="hero"><div class="mark">ER</div><div><small>ADMINISTRACIÓN GENERAL</small><h1>Errores del sistema</h1><p>Visor técnico del histórico registrado por la intranet.</p></div><div class="stats"><b>{{total}}</b><small>eventos</small></div><div class="stats danger"><b>{{criticalCount}}</b><small>errores críticos</small></div></header><p v-if="error" class="flash">{{error}}</p><section class="filters"><label>Archivo<select v-model="filters.archivo"><option value="">Todos los archivos</option><option v-for="file in files" :key="file.nombre" :value="file.nombre">{{file.nombre}} · {{file.tamanio}}</option></select></label><label>Nivel<select v-model="filters.nivel"><option value="">Todos</option><option value="error">Error</option><option value="critical">Crítico</option><option value="warning">Advertencia</option><option value="info">Información</option><option value="debug">Depuración</option></select></label><label>Buscar<input v-model.trim="filters.criterio" placeholder="Mensaje o contexto" @keyup.enter="load()"></label><label>Desde<input v-model="filters.desde" type="date"></label><label>Hasta<input v-model="filters.hasta" type="date"></label><div><button @click="load()">Consultar</button><button class="clear" @click="clear">Limpiar</button></div></section><div v-if="loading" class="empty">Leyendo archivos de registro…</div><div v-else-if="!rows.length" class="empty"><b>No se encontraron eventos</b><span>El sistema no registra errores para los filtros seleccionados.</span></div><section v-else class="table"><header><span>Nivel</span><span>Fecha</span><span>Mensaje</span><span>Archivo / entorno</span><span></span></header><article v-for="row in rows" :key="row.id"><span class="level" :class="row.nivel">{{levelName(row.nivel)}}</span><b>{{row.fecha}}</b><div class="message"><b>{{row.mensaje}}</b><small>{{row.contexto||'Sin contexto adicional'}}</small></div><div><b>{{row.archivo}}</b><small>{{row.entorno||'Aplicación'}}</small></div><button @click="selected=row">Ver detalle</button></article></section><footer v-if="last>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>Página {{filters.page}} de {{last}}</span><button :disabled="filters.page>=last" @click="load(filters.page+1)">Siguiente</button></footer><div v-if="selected" class="backdrop" @mousedown.self="selected=null"><section class="modal"><header><div><span class="level" :class="selected.nivel">{{levelName(selected.nivel)}}</span><h2>Detalle del evento</h2></div><button @click="selected=null">×</button></header><dl><div><dt>Fecha</dt><dd>{{selected.fecha}}</dd></div><div><dt>Archivo</dt><dd>{{selected.archivo}}</dd></div><div><dt>Entorno</dt><dd>{{selected.entorno||'Aplicación'}}</dd></div></dl><h3>Mensaje</h3><pre>{{selected.mensaje}}</pre><template v-if="selected.contexto"><h3>Contexto</h3><pre>{{selected.contexto}}</pre></template><template v-if="selected.traza"><h3>Traza técnica</h3><pre>{{selected.traza}}</pre></template></section></div></div></template>

<style scoped>
.page{--a:#334a61;color:#35444c}nav{margin-bottom:16px;color:#96a0a5;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid #a94348;border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:#a94348;font-weight:800}.hero small{color:#a94348;font-size:.52rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.28rem}.hero p{margin:0;color:#7c898f;font-size:.62rem}.stats{margin-left:auto;display:grid;text-align:center}.stats+.stats{margin-left:0}.stats b{font-size:.9rem}.stats small{color:#849096;font-size:.4rem}.stats.danger b{color:#a94348}.flash{padding:10px;color:#a13e43;background:#fff0f0;font-size:.6rem}.filters{margin-top:12px;padding:12px;display:grid;grid-template-columns:1.2fr .8fr 1.3fr .8fr .8fr auto;align-items:end;gap:8px;background:#fff}.filters label{font-size:.47rem}input,select{width:100%;padding:8px;border:1px solid #d7e0e3;border-radius:5px;font:inherit;font-size:.5rem}.filters button,.pages button{padding:8px 10px;border:0;border-radius:5px;color:#fff;background:var(--a);font-size:.47rem}.filters .clear{margin-left:4px;color:#68767c;background:#edf1f2}.table{margin-top:12px;background:#fff}.table>header,.table>article{padding:10px 12px;display:grid;grid-template-columns:.65fr .85fr 2fr 1fr .55fr;align-items:center;gap:10px;border-bottom:1px solid #e9edee}.table>header{color:#849096;background:#f4f6f7;font-size:.42rem}.table article{font-size:.46rem}.table article b,.table article small{display:block}.table small{color:#89949a;font-size:.4rem}.message{min-width:0}.message b,.message small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.table article>button{border:0;color:var(--a);background:none;font-size:.43rem}.level{width:max-content;padding:4px 7px;border-radius:10px;text-transform:uppercase;font-size:.38rem;font-weight:800}.error,.critical,.alert,.emergency{color:#9b3339;background:#fbe7e8}.warning{color:#82621b;background:#fff3d3}.info,.notice{color:#276b79;background:#e4f3f6}.debug{color:#5e6570;background:#edf0f3}.empty{margin-top:12px;padding:48px;display:grid;gap:5px;text-align:center;background:#fff;font-size:.58rem}.empty span{color:#89949a;font-size:.48rem}.pages{display:flex;justify-content:center;align-items:center;gap:10px;font-size:.48rem}.backdrop{position:fixed;z-index:100;inset:0;padding:16px;display:grid;place-items:center;background:#14283888}.modal{width:min(900px,100%);max-height:92vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex;align-items:start}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal h2{margin:7px 0;font-size:.9rem}.modal h3{margin:14px 0 5px;font-size:.55rem}.modal dl{display:flex;gap:25px}.modal dt{color:#89949a;font-size:.4rem}.modal dd{margin:2px 0;font-size:.48rem}.modal pre{padding:12px;overflow:auto;white-space:pre-wrap;border:1px solid #e0e6e8;border-radius:6px;background:#f7f9fa;font-size:.45rem;line-height:1.5}@media(max-width:900px){.filters{grid-template-columns:1fr 1fr 1fr}.table>header{display:none}.table>article{grid-template-columns:.7fr 1fr 2fr}}@media(max-width:560px){.hero{flex-wrap:wrap}.stats{margin-left:0}.filters,.table>article{grid-template-columns:1fr}.modal dl{flex-direction:column;gap:5px}}
</style>
